import { Club, Player, MatchFixture, LeagueTableRow, SeasonHistoryEntry } from '@/types/football-manager';

// Generates 22 rounds for 12 clubs using round-robin algorithm
export function generateSeasonFixtures(season: number, clubs: Club[]): MatchFixture[] {
  const n = clubs.length;
  const clubIds = clubs.map((c) => c.id);
  const rounds: MatchFixture[] = [];

  // Round robin for 11 rounds
  const tempIds = [...clubIds];
  const half = n / 2;

  const firstLegRounds: Array<Array<[string, string]>> = [];

  for (let r = 0; r < n - 1; r++) {
    const roundPairs: Array<[string, string]> = [];
    for (let i = 0; i < half; i++) {
      let home = tempIds[i];
      let away = tempIds[n - 1 - i];
      if ((i + r) % 2 === 1) {
        [home, away] = [away, home];
      }
      roundPairs.push([home, away]);
    }
    firstLegRounds.push(roundPairs);

    // Rotate array keeping first element fixed
    const last = tempIds.pop()!;
    tempIds.splice(1, 0, last);
  }

  // First leg (Jornadas 1 to 11)
  firstLegRounds.forEach((pairs, rIdx) => {
    const roundNum = rIdx + 1;
    pairs.forEach(([h, a], mIdx) => {
      rounds.push({
        id: `fix-s${season}-r${roundNum}-m${mIdx}`,
        season,
        round: roundNum,
        homeClubId: h,
        awayClubId: a,
        isPlayed: false,
      });
    });
  });

  // Second leg (Jornadas 12 to 22) - Inverted home/away
  firstLegRounds.forEach((pairs, rIdx) => {
    const roundNum = rIdx + 12;
    pairs.forEach(([h, a], mIdx) => {
      rounds.push({
        id: `fix-s${season}-r${roundNum}-m${mIdx}`,
        season,
        round: roundNum,
        homeClubId: a, // Inverted
        awayClubId: h,
        isPlayed: false,
      });
    });
  });

  return rounds;
}

// Simulates background AI matches for a round
export function simulateAiMatchesForRound(
  round: number,
  userClubId: string,
  fixtures: MatchFixture[],
  clubsMap: Record<string, Club>,
  players: Player[]
): { updatedFixtures: MatchFixture[]; updatedPlayers: Player[] } {
  const playersCopy = [...players];
  const fixturesCopy = [...fixtures];

  const roundFixtures = fixturesCopy.filter(
    (f) => f.round === round && !f.isPlayed && f.homeClubId !== userClubId && f.awayClubId !== userClubId
  );

  roundFixtures.forEach((fix) => {
    const hClub = clubsMap[fix.homeClubId];
    const aClub = clubsMap[fix.awayClubId];
    if (!hClub || !aClub) return;

    const hPwr = hClub.level + 2.5;
    const aPwr = aClub.level;

    // Realistic Poisson-like goals
    const hLambda = Math.max(0.4, (hPwr / aPwr) * 1.4);
    const aLambda = Math.max(0.3, (aPwr / hPwr) * 1.1);

    const calcGoals = (lambda: number) => {
      let g = 0;
      let p = Math.exp(-lambda);
      let f = p;
      const u = Math.random();
      while (u > f && g < 7) {
        g++;
        p = (p * lambda) / g;
        f += p;
      }
      return g;
    };

    const hScore = calcGoals(hLambda);
    const aScore = calcGoals(aLambda);

    fix.homeScore = hScore;
    fix.awayScore = aScore;
    fix.isPlayed = true;

    // Attribute goals and assists to top forwards/midfielders of AI clubs
    const hStrikers = playersCopy.filter((p) => p.clubId === hClub.id && ['DC', 'EI', 'ED'].includes(p.position));
    const aStrikers = playersCopy.filter((p) => p.clubId === aClub.id && ['DC', 'EI', 'ED'].includes(p.position));

    for (let i = 0; i < hScore; i++) {
      const scorer = hStrikers[Math.floor(Math.random() * hStrikers.length)];
      if (scorer) scorer.seasonGoals += 1;
    }
    for (let i = 0; i < aScore; i++) {
      const scorer = aStrikers[Math.floor(Math.random() * aStrikers.length)];
      if (scorer) scorer.seasonGoals += 1;
    }

    // Update match count
    playersCopy.filter((p) => p.clubId === hClub.id || p.clubId === aClub.id).forEach((p) => {
      p.seasonMatches += 1;
    });
  });

  return { updatedFixtures: fixturesCopy, updatedPlayers: playersCopy };
}

// Compute League Table sorted by Points, GD, GF
export function computeLeagueTable(clubs: Club[], fixtures: MatchFixture[]): LeagueTableRow[] {
  const tableMap: Record<string, LeagueTableRow> = {};

  clubs.forEach((c) => {
    tableMap[c.id] = {
      clubId: c.id,
      clubName: c.name,
      shortName: c.shortName,
      played: 0,
      won: 0,
      drawn: 0,
      lost: 0,
      goalsFor: 0,
      goalsAgainst: 0,
      goalDifference: 0,
      points: 0,
      formHistory: [],
    };
  });

  fixtures.filter((f) => f.isPlayed && f.homeScore !== undefined && f.awayScore !== undefined).forEach((f) => {
    const hRow = tableMap[f.homeClubId];
    const aRow = tableMap[f.awayClubId];
    if (!hRow || !aRow) return;

    const hs = f.homeScore!;
    const as = f.awayScore!;

    hRow.played += 1;
    aRow.played += 1;
    hRow.goalsFor += hs;
    hRow.goalsAgainst += as;
    aRow.goalsFor += as;
    aRow.goalsAgainst += hs;

    if (hs > as) {
      hRow.won += 1;
      hRow.points += 3;
      hRow.formHistory.push('W');
      aRow.lost += 1;
      aRow.formHistory.push('L');
    } else if (hs === as) {
      hRow.drawn += 1;
      hRow.points += 1;
      hRow.formHistory.push('D');
      aRow.drawn += 1;
      aRow.points += 1;
      aRow.formHistory.push('D');
    } else {
      hRow.lost += 1;
      hRow.formHistory.push('L');
      aRow.won += 1;
      aRow.points += 3;
      aRow.formHistory.push('W');
    }

    hRow.goalDifference = hRow.goalsFor - hRow.goalsAgainst;
    aRow.goalDifference = aRow.goalsFor - aRow.goalsAgainst;
  });

  return Object.values(tableMap).sort((a, b) => {
    if (b.points !== a.points) return b.points - a.points;
    if (b.goalDifference !== a.goalDifference) return b.goalDifference - a.goalDifference;
    return b.goalsFor - a.goalsFor;
  });
}

// End of season rollover
export function advanceToNextSeason(
  currentSeason: number,
  userClubId: string,
  clubs: Club[],
  players: Player[],
  table: LeagueTableRow[]
): {
  newSeason: number;
  newClubs: Club[];
  newPlayers: Player[];
  newFixtures: MatchFixture[];
  seasonHistoryEntry: SeasonHistoryEntry;
} {
  const userPos = table.findIndex((r) => r.clubId === userClubId) + 1;
  const champion = table[0];

  // Prize money according to final position
  const prizePool = [
    500000000, 380000000, 300000000, 240000000, 200000000, 160000000,
    130000000, 110000000, 90000000, 75000000, 60000000, 50000000
  ];
  const userPrize = prizePool[userPos - 1] || 50000000;

  // Find top scorer
  const topScorer = [...players].sort((a, b) => b.seasonGoals - a.seasonGoals)[0];
  const topClub = clubs.find((c) => c.id === topScorer?.clubId);

  const historyEntry: SeasonHistoryEntry = {
    seasonNumber: currentSeason,
    championClubId: champion.clubId,
    championClubName: champion.clubName,
    userPosition: userPos,
    userClubId,
    userClubName: clubs.find((c) => c.id === userClubId)?.name || 'Mi Club',
    topScorerName: topScorer?.name || 'Desconocido',
    topScorerGoals: topScorer?.seasonGoals || 0,
    topScorerClubName: topClub?.name || 'Liga',
    prizeMoneyYen: userPrize,
  };

  // Evolve players: Age + 1, growth or decline, contracts - 1, reset season stats
  const evolvedPlayers: Player[] = players.map((p) => {
    const age = p.age + 1;
    let growth = 0;

    if (age <= 21) {
      growth = Math.floor(Math.random() * 4) + 1; // Youngsters grow +1 to +4
    } else if (age <= 25) {
      growth = Math.floor(Math.random() * 3); // Prime ages grow 0 to +2
    } else if (age >= 32) {
      growth = -Math.floor(Math.random() * 3) - 1; // Decline -1 to -3
    }

    const newOvr = Math.min(99, Math.max(50, p.overall + growth));
    const newStats = { ...p.stats };
    Object.keys(newStats).forEach((k) => {
      const key = k as keyof Player['stats'];
      newStats[key] = Math.min(99, Math.max(30, newStats[key] + growth));
    });

    return {
      ...p,
      age,
      overall: newOvr,
      stats: newStats,
      fitness: 100,
      morale: 80,
      form: 75,
      contractYears: Math.max(0, p.contractYears - 1),
      injuryWeeks: 0,
      isBanned: false,
      yellowCardsCount: 0,
      seasonMatches: 0,
      seasonGoals: 0,
      seasonAssists: 0,
      seasonYellowCards: 0,
      seasonRedCards: 0,
      seasonCleanSheets: 0,
      seasonAverageRating: 6.8,
    };
  });

  // Update clubs with prize money and renewed budget
  const evolvedClubs: Club[] = clubs.map((c) => {
    const pos = table.findIndex((r) => r.clubId === c.id) + 1;
    const prize = prizePool[pos - 1] || 50000000;
    return {
      ...c,
      cashYen: c.cashYen + prize,
      budgetYen: Math.round(c.budgetYen * 0.9) + Math.round(prize * 0.7),
    };
  });

  const nextSeason = currentSeason + 1;
  const newFixtures = generateSeasonFixtures(nextSeason, evolvedClubs);

  return {
    newSeason: nextSeason,
    newClubs: evolvedClubs,
    newPlayers: evolvedPlayers,
    newFixtures,
    seasonHistoryEntry: historyEntry,
  };
}

import { Club, Player, MatchEvent } from '@/types/football-manager';

export interface LiveMatchState {
  id: string;
  season: number;
  round: number;
  homeClub: Club;
  awayClub: Club;
  homeScore: number;
  awayScore: number;
  minute: number;
  isFinished: boolean;
  isPaused: boolean;
  speedMultiplier: number; // 1, 2, 5
  ballPosition: { x: number; y: number }; // 0-100%
  attackingTeamId: string;
  events: MatchEvent[];
  homeStats: {
    possession: number;
    shots: number;
    shotsOnTarget: number;
    chances: number;
    fouls: number;
    corners: number;
  };
  awayStats: {
    possession: number;
    shots: number;
    shotsOnTarget: number;
    chances: number;
    fouls: number;
    corners: number;
  };
  homeSubsRemaining: number;
  awaySubsRemaining: number;
  homeLineup: string[]; // Current 11 on pitch
  awayLineup: string[]; // Current 11 on pitch
  homeBench: string[];
  awayBench: string[];
  playerRatings: Record<string, number>; // playerId -> 6.0 to 10.0
}

export function initLiveMatch(
  season: number,
  round: number,
  homeClub: Club,
  awayClub: Club
): LiveMatchState {
  const ratings: Record<string, number> = {};
  [...homeClub.startingXI, ...awayClub.startingXI].forEach((id) => {
    ratings[id] = 6.0;
  });

  return {
    id: `live-m-${season}-${round}-${Date.now()}`,
    season,
    round,
    homeClub: JSON.parse(JSON.stringify(homeClub)),
    awayClub: JSON.parse(JSON.stringify(awayClub)),
    homeScore: 0,
    awayScore: 0,
    minute: 0,
    isFinished: false,
    isPaused: false,
    speedMultiplier: 1,
    ballPosition: { x: 50, y: 50 },
    attackingTeamId: homeClub.id,
    events: [
      {
        minute: 0,
        type: 'commentary',
        teamId: homeClub.id,
        description: `¡Arranca el partido en el ${homeClub.stadiumName}! ${homeClub.name} vs ${awayClub.name}`,
        ballZone: { x: 50, y: 50 },
      },
    ],
    homeStats: {
      possession: 50,
      shots: 0,
      shotsOnTarget: 0,
      chances: 0,
      fouls: 0,
      corners: 0,
    },
    awayStats: {
      possession: 50,
      shots: 0,
      shotsOnTarget: 0,
      chances: 0,
      fouls: 0,
      corners: 0,
    },
    homeSubsRemaining: 5,
    awaySubsRemaining: 5,
    homeLineup: [...homeClub.startingXI],
    awayLineup: [...awayClub.startingXI],
    homeBench: [...homeClub.substitutes],
    awayBench: [...awayClub.substitutes],
    playerRatings: ratings,
  };
}

// Simulates 1 minute of match action
export function tickLiveMatch(
  match: LiveMatchState,
  allPlayersMap: Record<string, Player>
): LiveMatchState {
  if (match.isFinished) return match;

  const currentMinute = match.minute + 1;
  const next = { ...match, minute: currentMinute };

  // Calculate team strengths with tactical modifiers
  const homePlayers = match.homeLineup.map((id) => allPlayersMap[id]).filter(Boolean);
  const awayPlayers = match.awayLineup.map((id) => allPlayersMap[id]).filter(Boolean);

  const homeGk = homePlayers.find((p) => p.position === 'POR') || homePlayers[0];
  const awayGk = awayPlayers.find((p) => p.position === 'POR') || awayPlayers[0];

  const getTeamPwr = (players: Player[], ment: Club['mentalidad']) => {
    const avg = players.reduce((s, p) => s + p.overall, 0) / Math.max(1, players.length);
    let mod = 1.0;
    if (ment === 'ultra_ofensiva') mod = 1.15;
    else if (ment === 'ofensiva') mod = 1.07;
    else if (ment === 'muy_defensiva') mod = 0.85;
    return avg * mod;
  };

  const homePwr = getTeamPwr(homePlayers, match.homeClub.mentalidad) + 2.5; // Ventaja de local
  const awayPwr = getTeamPwr(awayPlayers, match.awayClub.mentalidad);

  // Who gets the ball this minute?
  const homeProb = homePwr / (homePwr + awayPwr);
  const isHomeAttack = Math.random() < homeProb;
  const attTeam = isHomeAttack ? match.homeClub : match.awayClub;
  const defTeam = isHomeAttack ? match.awayClub : match.homeClub;
  const attPlayers = isHomeAttack ? homePlayers : awayPlayers;
  const defPlayers = isHomeAttack ? awayPlayers : homePlayers;
  const defGk = isHomeAttack ? awayGk : homeGk;

  next.attackingTeamId = attTeam.id;

  // Move ball position across 2D pitch
  const targetX = isHomeAttack ? 55 + Math.random() * 40 : 45 - Math.random() * 40;
  const targetY = 15 + Math.random() * 70;
  next.ballPosition = { x: Math.round(targetX), y: Math.round(targetY) };

  // Update dynamic possession
  const totalMins = Math.max(1, currentMinute);
  const homeAttacks = next.events.filter((e) => e.teamId === match.homeClub.id).length + (isHomeAttack ? 1 : 0);
  const rawPoss = Math.round((homeAttacks / (totalMins + 10)) * 100);
  next.homeStats.possession = Math.max(35, Math.min(65, rawPoss));
  next.awayStats.possession = 100 - next.homeStats.possession;

  // Random event roll for this minute
  const roll = Math.random();

  // 1. CHANCE OF DANGEROUS SHOT (approx 12-15% of minutes)
  if (roll < 0.14) {
    const shooter = attPlayers.filter((p) => ['DC', 'EI', 'ED', 'MCO'].includes(p.position))[Math.floor(Math.random() * 4)] || attPlayers[0];
    const passer = attPlayers.filter((p) => p.id !== shooter?.id && ['MC', 'MCO', 'EI', 'ED'].includes(p.position))[0];

    const statsObj = isHomeAttack ? next.homeStats : next.awayStats;
    statsObj.shots += 1;

    // Check shooter weapon (Blue Lock weapon trigger!)
    const weapon = shooter?.weapons?.[0];
    let shotPower = (shooter?.stats.shooting || 75) + (weapon ? weapon.level * 0.15 : 0);
    let gkPower = (defGk?.stats.goalkeeping || 70) + (defGk?.weapons?.[0] ? defGk.weapons[0].level * 0.15 : 0);

    // Flow state bonus
    if (shooter?.egoRating && shooter.egoRating > 88 && Math.random() < 0.3) {
      shotPower += 15;
      next.events.unshift({
        minute: currentMinute,
        type: 'flow',
        teamId: attTeam.id,
        playerId: shooter.id,
        playerName: shooter.name,
        description: `⚡ ¡FLOW ACTIVADO! ${shooter.name} entra en trance egoísta y visualiza la trayectoria perfecta.`,
        ballZone: next.ballPosition,
      });
    }

    // Shot evaluation
    const isTarget = Math.random() < 0.65;
    if (isTarget) {
      statsObj.shotsOnTarget += 1;

      // Is it a GOAL?
      const goalThreshold = 0.42 * (shotPower / (shotPower + gkPower));
      if (Math.random() < goalThreshold) {
        // GOAL!
        statsObj.chances += 1;
        if (isHomeAttack) {
          next.homeScore += 1;
        } else {
          next.awayScore += 1;
        }

        // Increase rating for scorer
        if (shooter) {
          next.playerRatings[shooter.id] = Math.min(10, (next.playerRatings[shooter.id] || 6.0) + 1.2);
        }
        if (passer) {
          next.playerRatings[passer.id] = Math.min(10, (next.playerRatings[passer.id] || 6.0) + 0.6);
        }

        let goalDesc = `⚽ ¡GOOOOOOL DE ${attTeam.name.toUpperCase()}! (${currentMinute}') `;
        if (weapon) {
          goalDesc += `¡${shooter.name} ejecuta su ${weapon.name} sin piedad directo al fondo de la red!`;
        } else {
          goalDesc += `¡Definición inapelable de ${shooter?.name || 'delantero'} tras desmarque al espacio!`;
        }
        if (passer) {
          goalDesc += ` (Asistencia de ${passer.name})`;
        }

        next.events.unshift({
          minute: currentMinute,
          type: 'goal',
          teamId: attTeam.id,
          playerId: shooter?.id,
          playerName: shooter?.name,
          assistPlayerId: passer?.id,
          assistPlayerName: passer?.name,
          description: goalDesc,
          ballZone: { x: isHomeAttack ? 95 : 5, y: 50 },
        });
      } else {
        // SAVED BY GOALKEEPER
        if (defGk) {
          next.playerRatings[defGk.id] = Math.min(10, (next.playerRatings[defGk.id] || 6.0) + 0.4);
        }
        const gkWeapon = defGk?.weapons?.[0];
        let saveDesc = `🧤 ¡PARADÓN de ${defGk?.name || 'el portero'}! `;
        if (gkWeapon) {
          saveDesc += `Desvía el misil de ${shooter?.name} con su habilidad especial ${gkWeapon.name}.`;
        } else {
          saveDesc += `Ataja el disparo ajustado de ${shooter?.name} con reflejos felinos.`;
        }

        next.events.unshift({
          minute: currentMinute,
          type: 'save',
          teamId: defTeam.id,
          playerId: defGk?.id,
          playerName: defGk?.name,
          description: saveDesc,
          ballZone: { x: isHomeAttack ? 92 : 8, y: 50 },
        });

        // Corner chance
        if (Math.random() < 0.5) {
          statsObj.corners += 1;
        }
      }
    } else {
      // Off target shot
      next.events.unshift({
        minute: currentMinute,
        type: 'shot',
        teamId: attTeam.id,
        playerId: shooter?.id,
        playerName: shooter?.name,
        description: `Ocasión de ${shooter?.name}: remate potente que sale rozando el travesaño del ${defTeam.name}.`,
        ballZone: next.ballPosition,
      });
    }
  }
  // 2. FOUL OR CARD (approx 4%)
  else if (roll > 0.96) {
    const defender = defPlayers[Math.floor(Math.random() * defPlayers.length)];
    const defStats = isHomeAttack ? next.awayStats : next.homeStats;
    defStats.fouls += 1;

    const isCard = Math.random() < 0.35;
    if (isCard && defender) {
      next.playerRatings[defender.id] = Math.max(4.0, (next.playerRatings[defender.id] || 6.0) - 0.5);

      next.events.unshift({
        minute: currentMinute,
        type: 'yellow_card',
        teamId: defTeam.id,
        playerId: defender.id,
        playerName: defender.name,
        description: `🟨 Tarjeta amarilla para ${defender.name} por una entrada dura cortando el contragolpe.`,
        ballZone: next.ballPosition,
      });
    }
  }
  // 3. MIDFIELD DUELL / METAVISION TACTICAL DUEL (approx 5%)
  else if (roll > 0.85 && roll <= 0.90) {
    const midAtt = attPlayers.find((p) => p.weapons.some((w) => w.type === 'vision')) || attPlayers[0];
    const midDef = defPlayers.find((p) => p.weapons.some((w) => w.type === 'defense')) || defPlayers[0];

    if (midAtt) {
      next.events.unshift({
        minute: currentMinute,
        type: 'commentary',
        teamId: attTeam.id,
        playerId: midAtt.id,
        playerName: midAtt.name,
        description: `👀 ${midAtt.name} escanea el campo con visión periférica y filtra un pase rompiendo líneas defensivas.`,
        ballZone: next.ballPosition,
      });
    }
  }

  // Check full time
  if (currentMinute >= 90) {
    next.isFinished = true;
    next.events.unshift({
      minute: 90,
      type: 'commentary',
      teamId: match.homeClub.id,
      description: `🏁 ¡FINAL DEL PARTIDO! Marcador definitivo: ${match.homeClub.name} ${next.homeScore} - ${next.awayScore} ${match.awayClub.name}.`,
      ballZone: { x: 50, y: 50 },
    });
  }

  return next;
}

// In-match player substitution
export function executeLiveSub(
  match: LiveMatchState,
  isHome: boolean,
  playerOutId: string,
  playerInId: string,
  allPlayersMap: Record<string, Player>
): LiveMatchState {
  const currentSubs = isHome ? match.homeSubsRemaining : match.awaySubsRemaining;
  if (currentSubs <= 0) return match;

  const currentLineup = isHome ? [...match.homeLineup] : [...match.awayLineup];
  const currentBench = isHome ? [...match.homeBench] : [...match.awayBench];

  const outIdx = currentLineup.indexOf(playerOutId);
  const inIdx = currentBench.indexOf(playerInId);

  if (outIdx === -1 || inIdx === -1) return match;

  // Swap
  currentLineup[outIdx] = playerInId;
  currentBench[inIdx] = playerOutId;

  const pOut = allPlayersMap[playerOutId];
  const pIn = allPlayersMap[playerInId];
  const team = isHome ? match.homeClub : match.awayClub;

  const newRatings = { ...match.playerRatings };
  if (!newRatings[playerInId]) newRatings[playerInId] = 6.0;

  const newEvents = [
    {
      minute: match.minute,
      type: 'sub' as const,
      teamId: team.id,
      playerId: playerInId,
      playerName: pIn?.name || 'Jugador',
      description: `🔄 Cambio en ${team.name}: entra ${pIn?.name || 'suplente'} sustituyendo a ${pOut?.name || 'titular'}.`,
      ballZone: match.ballPosition,
    },
    ...match.events,
  ];

  return {
    ...match,
    homeLineup: isHome ? currentLineup : match.homeLineup,
    awayLineup: !isHome ? currentLineup : match.awayLineup,
    homeBench: isHome ? currentBench : match.homeBench,
    awayBench: !isHome ? currentBench : match.awayBench,
    homeSubsRemaining: isHome ? currentSubs - 1 : match.homeSubsRemaining,
    awaySubsRemaining: !isHome ? currentSubs - 1 : match.awaySubsRemaining,
    events: newEvents,
    playerRatings: newRatings,
  };
}

import { create } from 'zustand';
import {
  Club,
  Player,
  MatchFixture,
  LeagueTableRow,
  TransferOffer,
  ClubLedgerEntry,
  DecisionEvent,
  SeasonHistoryEntry,
  TacticalMentalidad,
  TacticalPresion,
  TacticalPase,
  Formation,
} from '@/types/football-manager';
import { generateInitialClubsAndPlayers } from '@/engine/game-data';
import {
  generateSeasonFixtures,
  simulateAiMatchesForRound,
  computeLeagueTable,
  advanceToNextSeason,
} from '@/engine/season-engine';
import {
  LiveMatchState,
  initLiveMatch,
  tickLiveMatch,
  executeLiveSub,
} from '@/engine/match-engine-2d';
import { DECISION_EVENTS_POOL } from '@/engine/events-data';

const STORAGE_KEY = 'bluelock_football_manager_v2';

export interface GameStoreState {
  hasStarted: boolean;
  managerName: string;
  userClubId: string;
  currentSeason: number;
  currentRound: number; // 1 to 22
  clubs: Club[];
  players: Player[];
  fixtures: MatchFixture[];
  activeTab: 'office' | 'squad' | 'tactics' | 'live_match' | 'table' | 'market' | 'training' | 'finance' | 'inbox';
  liveMatch: LiveMatchState | null;
  boardTrust: number; // 0-100
  squadMorale: number; // 0-100
  trainingPlan: 'equilibrado' | 'fisico' | 'ofensivo' | 'defensivo' | 'descanso';
  youthPromotedThisSeason: boolean;
  activeDecisionEvent: DecisionEvent | null;
  transferOffers: TransferOffer[];
  ledger: ClubLedgerEntry[];
  seasonHistory: SeasonHistoryEntry[];
  isSacked: boolean;
  isSeasonCompleted: boolean;

  // Actions
  startNewGame: (managerName: string, clubId: string) => void;
  loadFromStorage: () => boolean;
  saveToStorage: () => void;
  setActiveTab: (tab: GameStoreState['activeTab']) => void;
  startMatchDay: () => void;
  tickMatchMinute: () => void;
  executeMatchSub: (outId: string, inId: string) => void;
  finishMatchDay: () => void;
  updateTactics: (mentalidad: TacticalMentalidad, presion: TacticalPresion, estiloPase: TacticalPase) => void;
  updateFormation: (formation: Formation) => void;
  swapStartingPlayer: (playerOutId: string, playerInId: string) => void;
  setRole: (role: 'captain' | 'penalty' | 'freekick', playerId: string) => void;
  setTrainingPlan: (plan: GameStoreState['trainingPlan']) => void;
  promoteYouthPlayer: () => { success: boolean; message: string };
  makeBuyOffer: (playerId: string, feeYen: number, wageYen: number, years: number) => { success: boolean; message: string };
  acceptSellOffer: (offerId: string) => void;
  rejectSellOffer: (offerId: string) => void;
  renewPlayerContract: (playerId: string, newWageYen: number, addYears: number) => { success: boolean; message: string };
  answerDecisionEvent: (optionIndex: number) => void;
  proceedToNextSeason: () => void;
  exportGameJson: () => string;
  importGameJson: (jsonStr: string) => { success: boolean; message: string };
  resetCareerGame: () => void;
}

export const useGameStore = create<GameStoreState>((set, get) => ({
  hasStarted: false,
  managerName: 'Ego Jinpachi',
  userClubId: 'club-bm',
  currentSeason: 1,
  currentRound: 1,
  clubs: [],
  players: [],
  fixtures: [],
  activeTab: 'office',
  liveMatch: null,
  boardTrust: 75,
  squadMorale: 80,
  trainingPlan: 'equilibrado',
  youthPromotedThisSeason: false,
  activeDecisionEvent: null,
  transferOffers: [],
  ledger: [],
  seasonHistory: [],
  isSacked: false,
  isSeasonCompleted: false,

  startNewGame: (managerName: string, clubId: string) => {
    const { clubs, players } = generateInitialClubsAndPlayers();
    const fixtures = generateSeasonFixtures(1, clubs);

    const userClub = clubs.find((c) => c.id === clubId) || clubs[0];

    const initialLedger: ClubLedgerEntry[] = [
      {
        id: `led-0-${Date.now()}`,
        season: 1,
        round: 1,
        type: 'patrocinio',
        concept: 'Presupuesto Inicial y Patrocinio de Temporada',
        amountYen: userClub.cashYen,
        dateStr: 'Inicio de Temporada 1',
      },
    ];

    const newState: Partial<GameStoreState> = {
      hasStarted: true,
      managerName: managerName.trim() || 'Ego Jinpachi',
      userClubId: userClub.id,
      currentSeason: 1,
      currentRound: 1,
      clubs,
      players,
      fixtures,
      activeTab: 'office',
      liveMatch: null,
      boardTrust: 75,
      squadMorale: 80,
      trainingPlan: 'equilibrado',
      youthPromotedThisSeason: false,
      activeDecisionEvent: null,
      transferOffers: [],
      ledger: initialLedger,
      seasonHistory: [],
      isSacked: false,
      isSeasonCompleted: false,
    };

    set(newState);
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(newState));
    } catch (e) {
      console.warn('LocalStorage error:', e);
    }
  },

  loadFromStorage: () => {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      if (!data) return false;
      const parsed = JSON.parse(data);
      if (parsed && parsed.clubs && parsed.players && parsed.fixtures) {
        set(parsed);
        return true;
      }
    } catch (e) {
      console.error('Failed to load game from storage', e);
    }
    return false;
  },

  saveToStorage: () => {
    try {
      const state = get();
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) {
      console.warn('LocalStorage save failed', e);
    }
  },

  setActiveTab: (tab) => set({ activeTab: tab }),

  startMatchDay: () => {
    const { fixtures, currentSeason, currentRound, userClubId, clubs } = get();
    const userFixture = fixtures.find(
      (f) => f.round === currentRound && (f.homeClubId === userClubId || f.awayClubId === userClubId)
    );
    if (!userFixture) return;

    const homeClub = clubs.find((c) => c.id === userFixture.homeClubId);
    const awayClub = clubs.find((c) => c.id === userFixture.awayClubId);
    if (!homeClub || !awayClub) return;

    const liveMatch = initLiveMatch(currentSeason, currentRound, homeClub, awayClub);
    set({ liveMatch, activeTab: 'live_match' });
  },

  tickMatchMinute: () => {
    const { liveMatch, players } = get();
    if (!liveMatch || liveMatch.isFinished) return;

    const playersMap = players.reduce((acc, p) => {
      acc[p.id] = p;
      return acc;
    }, {} as Record<string, Player>);

    const updated = tickLiveMatch(liveMatch, playersMap);
    set({ liveMatch: updated });
  },

  executeMatchSub: (outId: string, inId: string) => {
    const { liveMatch, players, userClubId } = get();
    if (!liveMatch) return;

    const isHome = liveMatch.homeClub.id === userClubId;
    const playersMap = players.reduce((acc, p) => {
      acc[p.id] = p;
      return acc;
    }, {} as Record<string, Player>);

    const updated = executeLiveSub(liveMatch, isHome, outId, inId, playersMap);
    set({ liveMatch: updated });
  },

  finishMatchDay: () => {
    const {
      liveMatch,
      fixtures,
      currentRound,
      currentSeason,
      userClubId,
      clubs,
      players,
      trainingPlan,
      ledger,
      boardTrust,
      squadMorale,
    } = get();

    if (!liveMatch) return;

    // 1. Mark user fixture as played
    const updatedFixtures = fixtures.map((f) => {
      if (f.round === currentRound && (f.homeClubId === userClubId || f.awayClubId === userClubId)) {
        return {
          ...f,
          isPlayed: true,
          homeScore: liveMatch.homeScore,
          awayScore: liveMatch.awayScore,
          events: liveMatch.events,
          homeStats: liveMatch.homeStats,
          awayStats: liveMatch.awayStats,
        };
      }
      return f;
    });

    // 2. Clubs map
    const clubsMap = clubs.reduce((acc, c) => {
      acc[c.id] = c;
      return acc;
    }, {} as Record<string, Club>);

    // 3. Simulate all AI matches for this round
    const { updatedFixtures: finalFixtures, updatedPlayers } = simulateAiMatchesForRound(
      currentRound,
      userClubId,
      updatedFixtures,
      clubsMap,
      players
    );

    // 4. Update stats for user players from the live match
    const userIsHome = liveMatch.homeClub.id === userClubId;
    const userLineup = userIsHome ? liveMatch.homeLineup : liveMatch.awayLineup;
    const userWon = userIsHome ? liveMatch.homeScore > liveMatch.awayScore : liveMatch.awayScore > liveMatch.homeScore;
    const userDrew = liveMatch.homeScore === liveMatch.awayScore;

    const finalPlayers = updatedPlayers.map((p) => {
      if (userLineup.includes(p.id)) {
        const rating = liveMatch.playerRatings[p.id] || 6.5;
        // Goals scored by this player
        const playerGoals = liveMatch.events.filter(
          (e) => e.type === 'goal' && e.playerId === p.id && e.teamId === userClubId
        ).length;
        const playerAssists = liveMatch.events.filter(
          (e) => e.type === 'goal' && e.assistPlayerId === p.id && e.teamId === userClubId
        ).length;

        // Apply training recovery and growth
        let staminaRecovery = 25;
        let moraleBonus = userWon ? 4 : userDrew ? 0 : -3;
        if (trainingPlan === 'descanso') staminaRecovery = 35;
        else if (trainingPlan === 'fisico') staminaRecovery = 15;

        return {
          ...p,
          seasonMatches: p.seasonMatches + 1,
          seasonGoals: p.seasonGoals + playerGoals,
          seasonAssists: p.seasonAssists + playerAssists,
          fitness: Math.min(100, Math.max(50, p.fitness - 15 + staminaRecovery)),
          morale: Math.min(100, Math.max(30, p.morale + moraleBonus)),
          form: Math.min(100, Math.max(40, Math.round(p.form * 0.7 + rating * 3.5))),
          marketValueYen: Math.round(p.marketValueYen * (1 + (playerGoals * 0.08) + (userWon ? 0.02 : 0))),
        };
      }
      return p;
    });

    // 5. Financial updates (Ticket revenue if home, weekly wages)
    const userClub = clubs.find((c) => c.id === userClubId)!;
    const updatedLedger = [...ledger];

    let newCash = userClub.cashYen;
    if (userIsHome) {
      const attendance = Math.round(userClub.stadiumCapacity * (0.7 + Math.random() * 0.3));
      const ticketRevenue = attendance * userClub.ticketPriceYen;
      newCash += ticketRevenue;
      updatedLedger.push({
        id: `led-t-${currentRound}-${Date.now()}`,
        season: currentSeason,
        round: currentRound,
        type: 'taquilla',
        concept: `Taquilla J${currentRound} (${attendance.toLocaleString()} espectadores)`,
        amountYen: ticketRevenue,
        dateStr: `Jornada ${currentRound}`,
      });
    }

    // Weekly wages
    const totalWeeklyWage = finalPlayers
      .filter((p) => p.clubId === userClubId)
      .reduce((sum, p) => sum + p.weeklyWageYen, 0);
    newCash -= totalWeeklyWage;
    updatedLedger.push({
      id: `led-w-${currentRound}-${Date.now()}`,
      season: currentSeason,
      round: currentRound,
      type: 'salarios',
      concept: `Pago de Salarios Semanales (Plantilla)`,
      amountYen: -totalWeeklyWage,
      dateStr: `Jornada ${currentRound}`,
    });

    // Update club cash
    const updatedClubs = clubs.map((c) => (c.id === userClubId ? { ...c, cashYen: newCash } : c));

    // Board trust and morale
    const trustDelta = userWon ? 5 : userDrew ? 0 : -6;
    const newBoardTrust = Math.min(100, Math.max(5, boardTrust + trustDelta));
    const newSquadMorale = Math.min(100, Math.max(20, squadMorale + (userWon ? 6 : userDrew ? 0 : -5)));

    // Check if season is complete (Round 22 finished)
    const isSeasonCompleted = currentRound >= 22;

    // Pick random decision event occasionally (every 3-4 rounds)
    let nextDecisionEvent: DecisionEvent | null = null;
    if (!isSeasonCompleted && (currentRound % 3 === 0 || Math.random() < 0.35)) {
      nextDecisionEvent = DECISION_EVENTS_POOL[Math.floor(Math.random() * DECISION_EVENTS_POOL.length)];
    }

    set({
      fixtures: finalFixtures,
      players: finalPlayers,
      clubs: updatedClubs,
      ledger: updatedLedger,
      boardTrust: newBoardTrust,
      squadMorale: newSquadMorale,
      currentRound: isSeasonCompleted ? currentRound : currentRound + 1,
      isSeasonCompleted,
      isSacked: newBoardTrust < 15,
      activeDecisionEvent: nextDecisionEvent,
      activeTab: isSeasonCompleted ? 'table' : 'office',
      liveMatch: null,
    });

    get().saveToStorage();
  },

  updateTactics: (mentalidad, presion, estiloPase) => {
    const { clubs, userClubId } = get();
    const updated = clubs.map((c) =>
      c.id === userClubId ? { ...c, mentalidad, presion, estiloPase } : c
    );
    set({ clubs: updated });
    get().saveToStorage();
  },

  updateFormation: (formation) => {
    const { clubs, userClubId } = get();
    const updated = clubs.map((c) => (c.id === userClubId ? { ...c, formation } : c));
    set({ clubs: updated });
    get().saveToStorage();
  },

  swapStartingPlayer: (playerOutId, playerInId) => {
    const { clubs, userClubId } = get();
    const userClub = clubs.find((c) => c.id === userClubId);
    if (!userClub) return;

    const xi = [...userClub.startingXI];
    const bench = [...userClub.substitutes];

    const outIdx = xi.indexOf(playerOutId);
    const inIdx = bench.indexOf(playerInId);

    if (outIdx !== -1 && inIdx !== -1) {
      xi[outIdx] = playerInId;
      bench[inIdx] = playerOutId;
    } else if (outIdx !== -1 && xi.indexOf(playerInId) !== -1) {
      // Swap positions on pitch
      const pos2 = xi.indexOf(playerInId);
      xi[outIdx] = playerInId;
      xi[pos2] = playerOutId;
    }

    const updated = clubs.map((c) =>
      c.id === userClubId ? { ...c, startingXI: xi, substitutes: bench } : c
    );
    set({ clubs: updated });
    get().saveToStorage();
  },

  setRole: (role, playerId) => {
    const { clubs, userClubId } = get();
    const updated = clubs.map((c) => {
      if (c.id === userClubId) {
        if (role === 'captain') return { ...c, captainId: playerId };
        if (role === 'penalty') return { ...c, penaltyTakerId: playerId };
        if (role === 'freekick') return { ...c, freeKickTakerId: playerId };
      }
      return c;
    });
    set({ clubs: updated });
    get().saveToStorage();
  },

  setTrainingPlan: (plan) => {
    set({ trainingPlan: plan });
    get().saveToStorage();
  },

  promoteYouthPlayer: () => {
    const { youthPromotedThisSeason, clubs, players, userClubId, currentSeason, ledger } = get();
    if (youthPromotedThisSeason) {
      return { success: false, message: 'Ya has promocionado a una promesa de la cantera esta temporada.' };
    }

    const userClub = clubs.find((c) => c.id === userClubId);
    const promotionCost = 60000000; // 60M Yen
    if (!userClub || userClub.cashYen < promotionCost) {
      return { success: false, message: 'Se necesitan al menos 60.000.000 ¥ en caja para la formación del canterano.' };
    }

    const firstNames = ['Seiichi', 'Takuma', 'Kazuya', 'Ryosuke', 'Taiki', 'Shinji', 'Ren'];
    const lastNames = ['Nakamura', 'Fujiwara', 'Matsuda', 'Onda', 'Shibata', 'Hayashi'];
    const name = `${firstNames[Math.floor(Math.random() * firstNames.length)]} ${lastNames[Math.floor(Math.random() * lastNames.length)]}`;

    const positions: Player['position'][] = ['DC', 'EI', 'ED', 'MCO', 'MC', 'DFC'];
    const pos = positions[Math.floor(Math.random() * positions.length)];
    const baseStat = userClub.level - 4;

    const newYouth: Player = {
      id: `youth-promoted-${Date.now()}`,
      clubId: userClubId,
      name: `${name} (Cantera)`,
      age: 16,
      nationality: 'Japón',
      position: pos,
      overall: baseStat,
      potential: Math.min(99, baseStat + 15),
      stats: {
        pace: baseStat + Math.floor(Math.random() * 8),
        shooting: pos === 'DC' ? baseStat + 5 : baseStat - 5,
        passing: baseStat + 2,
        dribbling: baseStat + 4,
        defense: pos === 'DFC' ? baseStat + 6 : baseStat - 10,
        physical: baseStat + 3,
        goalkeeping: 15,
      },
      weapons: [
        {
          name: 'Despertar de Cantera',
          type: 'striker',
          level: 86,
          description: 'Hambre pura descubierta en las pruebas de selección de Blue Lock',
        },
      ],
      egoRating: 88,
      flowState: false,
      fitness: 100,
      morale: 95,
      form: 80,
      marketValueYen: 50000000,
      weeklyWageYen: 1200000,
      contractYears: 4,
      injuryWeeks: 0,
      isBanned: false,
      yellowCardsCount: 0,
      seasonMatches: 0,
      seasonGoals: 0,
      seasonAssists: 0,
      seasonYellowCards: 0,
      seasonRedCards: 0,
      seasonCleanSheets: 0,
      seasonAverageRating: 7.0,
    };

    const updatedClubs = clubs.map((c) =>
      c.id === userClubId ? { ...c, cashYen: c.cashYen - promotionCost } : c
    );

    const updatedLedger: ClubLedgerEntry[] = [
      ...ledger,
      {
        id: `led-y-${Date.now()}`,
        season: currentSeason,
        round: get().currentRound,
        type: 'cantera',
        concept: `Promoción de Cantera (${newYouth.name})`,
        amountYen: -promotionCost,
        dateStr: `Temporada ${currentSeason}`,
      },
    ];

    set({
      players: [newYouth, ...players],
      clubs: updatedClubs,
      ledger: updatedLedger,
      youthPromotedThisSeason: true,
    });

    get().saveToStorage();
    return { success: true, message: `¡${newYouth.name} se une al primer equipo con 16 años y 88 de potencial!` };
  },

  makeBuyOffer: (playerId, feeYen, wageYen, years) => {
    const { players, clubs, userClubId, currentRound, ledger, currentSeason } = get();
    // Check transfer windows (Rounds 1-4 or 11-14)
    const isWindowOpen = currentRound <= 4 || (currentRound >= 11 && currentRound <= 14);
    if (!isWindowOpen) {
      return { success: false, message: 'La ventana de fichajes está cerrada. Se abrirá en las Jornadas 1-4 y 11-14.' };
    }

    const player = players.find((p) => p.id === playerId);
    const userClub = clubs.find((c) => c.id === userClubId);
    if (!player || !userClub) return { success: false, message: 'Datos inválidos.' };

    if (player.clubId === userClubId) {
      return { success: false, message: 'Este jugador ya pertenece a tu club.' };
    }

    if (userClub.cashYen < feeYen || userClub.budgetYen < feeYen) {
      return { success: false, message: 'Fondos o presupuesto de fichajes insuficiente.' };
    }

    // AI Acceptance algorithm
    const minAcceptableFee = player.marketValueYen * 0.9;
    const minAcceptableWage = player.weeklyWageYen * 1.1;

    if (feeYen < minAcceptableFee) {
      return {
        success: false,
        message: `El club propietario ha rechazado la oferta. Exigen al menos ${(minAcceptableFee).toLocaleString()} ¥.`,
      };
    }

    if (wageYen < minAcceptableWage) {
      return {
        success: false,
        message: `El jugador considera insuficiente el salario propuesto. Solicita al menos ${(minAcceptableWage).toLocaleString()} ¥ semanales.`,
      };
    }

    // Success! Complete transfer
    const updatedPlayers = players.map((p) => {
      if (p.id === playerId) {
        return {
          ...p,
          clubId: userClubId,
          weeklyWageYen: wageYen,
          contractYears: years,
          morale: 90,
        };
      }
      return p;
    });

    const updatedClubs = clubs.map((c) => {
      if (c.id === userClubId) {
        return {
          ...c,
          cashYen: c.cashYen - feeYen,
          budgetYen: c.budgetYen - feeYen,
          substitutes: [...c.substitutes, playerId],
        };
      }
      if (c.id === player.clubId) {
        return {
          ...c,
          cashYen: c.cashYen + feeYen,
          budgetYen: c.budgetYen + feeYen,
          startingXI: c.startingXI.filter((id) => id !== playerId),
          substitutes: c.substitutes.filter((id) => id !== playerId),
        };
      }
      return c;
    });

    const updatedLedger: ClubLedgerEntry[] = [
      ...ledger,
      {
        id: `led-b-${Date.now()}`,
        season: currentSeason,
        round: currentRound,
        type: 'fichaje_compra',
        concept: `Fichaje de ${player.name}`,
        amountYen: -feeYen,
        dateStr: `Jornada ${currentRound}`,
      },
    ];

    set({ players: updatedPlayers, clubs: updatedClubs, ledger: updatedLedger });
    get().saveToStorage();

    return { success: true, message: `¡Fichaje completado! ${player.name} firma por ${years} temporadas.` };
  },

  acceptSellOffer: (offerId) => {
    const { transferOffers, players, clubs, userClubId, ledger, currentSeason, currentRound } = get();
    const offer = transferOffers.find((o) => o.id === offerId);
    if (!offer) return;

    const player = players.find((p) => p.id === offer.playerId);
    if (!player) return;

    const updatedPlayers = players.map((p) => (p.id === offer.playerId ? { ...p, clubId: offer.buyerClubId } : p));

    const updatedClubs = clubs.map((c) => {
      if (c.id === userClubId) {
        return {
          ...c,
          cashYen: c.cashYen + offer.offeredFeeYen,
          budgetYen: c.budgetYen + Math.round(offer.offeredFeeYen * 0.8),
          startingXI: c.startingXI.filter((id) => id !== offer.playerId),
          substitutes: c.substitutes.filter((id) => id !== offer.playerId),
        };
      }
      return c;
    });

    const updatedLedger: ClubLedgerEntry[] = [
      ...ledger,
      {
        id: `led-s-${Date.now()}`,
        season: currentSeason,
        round: currentRound,
        type: 'fichaje_venta',
        concept: `Venta de ${player.name} al ${offer.buyerClubName}`,
        amountYen: offer.offeredFeeYen,
        dateStr: `Jornada ${currentRound}`,
      },
    ];

    set({
      players: updatedPlayers,
      clubs: updatedClubs,
      ledger: updatedLedger,
      transferOffers: transferOffers.filter((o) => o.id !== offerId),
    });

    get().saveToStorage();
  },

  rejectSellOffer: (offerId) => {
    set((state) => ({
      transferOffers: state.transferOffers.filter((o) => o.id !== offerId),
    }));
    get().saveToStorage();
  },

  renewPlayerContract: (playerId, newWageYen, addYears) => {
    const { players, clubs, userClubId } = get();
    const userClub = clubs.find((c) => c.id === userClubId);
    const player = players.find((p) => p.id === playerId);
    if (!player || !userClub) return { success: false, message: 'Jugador no encontrado.' };

    const minAcceptableWage = player.weeklyWageYen * 1.15;
    if (newWageYen < minAcceptableWage) {
      return {
        success: false,
        message: `El jugador exige un incremento del 15% (mínimo ${(minAcceptableWage).toLocaleString()} ¥/semana).`,
      };
    }

    const updatedPlayers = players.map((p) =>
      p.id === playerId
        ? {
            ...p,
            weeklyWageYen: newWageYen,
            contractYears: p.contractYears + addYears,
            morale: Math.min(100, p.morale + 10),
          }
        : p
    );

    set({ players: updatedPlayers });
    get().saveToStorage();
    return { success: true, message: `Contrato de ${player.name} renovado por ${addYears} años adicionales.` };
  },

  answerDecisionEvent: (optionIndex) => {
    const { activeDecisionEvent, clubs, userClubId, boardTrust, squadMorale } = get();
    if (!activeDecisionEvent) return;

    const option = activeDecisionEvent.options[optionIndex];
    if (!option) return;

    let newTrust = boardTrust;
    let newMorale = squadMorale;
    let newClubs = clubs;

    if (option.impact.boardTrustChange) {
      newTrust = Math.min(100, Math.max(0, newTrust + option.impact.boardTrustChange));
    }
    if (option.impact.squadMoraleChange) {
      newMorale = Math.min(100, Math.max(0, newMorale + option.impact.squadMoraleChange));
    }
    if (option.impact.budgetChangeYen) {
      newClubs = clubs.map((c) =>
        c.id === userClubId
          ? {
              ...c,
              cashYen: c.cashYen + option.impact.budgetChangeYen!,
              budgetYen: c.budgetYen + option.impact.budgetChangeYen!,
            }
          : c
      );
    }

    set({
      activeDecisionEvent: null,
      boardTrust: newTrust,
      squadMorale: newMorale,
      clubs: newClubs,
    });

    get().saveToStorage();
  },

  proceedToNextSeason: () => {
    const { currentSeason, userClubId, clubs, players, fixtures, seasonHistory, ledger } = get();
    const table = computeLeagueTable(clubs, fixtures);

    const { newSeason, newClubs, newPlayers, newFixtures, seasonHistoryEntry } = advanceToNextSeason(
      currentSeason,
      userClubId,
      clubs,
      players,
      table
    );

    const prizeEntry: ClubLedgerEntry = {
      id: `led-p-${newSeason}-${Date.now()}`,
      season: newSeason,
      round: 1,
      type: 'premios',
      concept: `Premios de Clasificación Temporada ${currentSeason} (Puesto ${seasonHistoryEntry.userPosition}º)`,
      amountYen: seasonHistoryEntry.prizeMoneyYen,
      dateStr: `Inicio Temporada ${newSeason}`,
    };

    set({
      currentSeason: newSeason,
      currentRound: 1,
      clubs: newClubs,
      players: newPlayers,
      fixtures: newFixtures,
      seasonHistory: [seasonHistoryEntry, ...seasonHistory],
      ledger: [prizeEntry, ...ledger],
      youthPromotedThisSeason: false,
      isSeasonCompleted: false,
      activeTab: 'office',
    });

    get().saveToStorage();
  },

  exportGameJson: () => {
    return JSON.stringify(get(), null, 2);
  },

  importGameJson: (jsonStr) => {
    try {
      const parsed = JSON.parse(jsonStr);
      if (parsed.clubs && parsed.players && parsed.fixtures && parsed.currentSeason) {
        set(parsed);
        get().saveToStorage();
        return { success: true, message: '¡Partida importada con éxito!' };
      }
      return { success: false, message: 'Formato de archivo inválido.' };
    } catch (e: any) {
      return { success: false, message: 'Error al procesar el archivo JSON.' };
    }
  },

  resetCareerGame: () => {
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch (e) {}
    set({
      hasStarted: false,
      clubs: [],
      players: [],
      fixtures: [],
      liveMatch: null,
    });
  },
}));

